      formula: { tex: 'x^0 = 1 \\qquad x^{-n} = \\dfrac{1}{x^n}', note: 'Each step down the staircase divides by the base once more.', parts: [{ sym: 'x^0', means: 'one step below x, so it lands on 1', tone: 'accent' }, { sym: 'x^{-n}', means: 'flips to a fraction; it never turns negative', tone: 'warn' }] },
